 catch(e){if(!ok())return;$("#chart").innerHTML=`<div class="placeholder">${esc(e.message)}. Nhịp Đầu Tư không tự tạo giá thay thế.</div>`;$("#cp-px").innerHTML="";$("#p-sig").innerHTML=""}
