 perf(){$$("#pf-per button").forEach(b=>b.onclick=()=>{perDays=+b.dataset.v;sessionStorage.pfPer=perDays;perf=null;draw()});const run=async()=>{const el=$("#pf-pc");if(!pfAct().positions.length){el.innerHTML='<p class="muted">Danh mục trống.</p>';return}try{perf=perf||await pfPerf(pfAct(),perDays);if(!ok()||!$("#pf-pc"))return;const d=perf.pr-perf.ir;$("#pf-pc").innerHTML=`<div class="stats"><div><small>Danh mục (mô phỏng)</small><b class="${perf.pr<0?"dn":"up"}">${pc(+perf.pr.toFixed(2))}</b></div><div><small>VN-Index</small><b class="${perf.ir<0?"dn":"up"}">${pc(+perf.ir.toFixed(2))}</b></div><div><small>Chênh lệch</small><b class="${d<0?"dn":"up"}">${d>0?"+":""}${num(d)} đ.%</b></div></div>${pfLine(perf.pts)}<div class="pf-leg"><span style="color:#3b6fd4">━ Danh mục</span><span style="color:#8a99a8">━ VN-Index</span></div>${perf.miss.length?`<p class="source-note">Không có giá lịch sử cho: ${perf.miss.join(", ")}.</p>`:""}`}catch(e){const x=$("#pf-pc");if(x)x.innerHTML=err(e,"Không tính được hiệu suất")}};run()},
