 $("#tx-f").onsubmit=async e=>{e.preventDefault();const p=pfAct();{const sy0=$("#tx-s").value.toUpperCase().trim(),ph=pfHouse(p);if(sy0&&!isIdx(sy0)&&hOf(sy0)!==ph)return toast(`Mã ${sy0} thuộc sàn ${hNm(hOf(sy0))}. Danh mục này thuộc sàn ${hNm(ph)} — chuyển sang nhà ${hNm(hOf(sy0))} để ghi.`,1)}const m=pfApply(p,{type:$("#tx-ty").value,symbol:$("#tx-s").value,qty:pnum($("#tx-q").value),price:pnum($("#tx-p").value),fee:pnum($("#tx-fee").value)||0,amount:pnum($("#tx-a").value)||0,date:$("#tx-d").value,note:$("#tx-n").value,cash:$("#tx-c").checked});if(m)return toast(m,1);try{const ty=$("#tx-ty").value,sy=$("#tx-s").value.toUpperCase().trim();if(window.NHIPOrders&&Array.isArray(p.orders)&&p.orders.length&&(ty==="sell"||ty==="pos")){const f=JSON.parse(sessionStorage.pfFillOrder||"null");if(ty==="sell"&&f&&f.sym===sy&&f.pid===p.id){const o=p.orders.find(x=>x.id===f.id),q=pnum($("#tx-q").value);if(o){if(q>=o.qty)p.orders=p.orders.filter(x=>x!==o);else o.qty-=q}}sessionStorage.removeItem("pfFillOrder");NHIPOrders.reconcile(p,sy)}}catch{}if(await pfSave())toast("Đã ghi giao dịch");load()};
