/* Biểu đồ v26: module charts.js; nếu thiếu/lỗi thì quay về bản biểu đồ cũ (vOverview) để không làm hỏng trang. */
async function vChartsRoute(){try{if(window.vCharts)await window.vCharts();else vOverview()}catch(e){console.error("Biểu đồ v26 lỗi, dùng bản dự phòng:",e);vOverview()}}
/* Phân tích v28: dùng giao diện biểu đồ gọn như mục Biểu đồ (analysis-view.js); nếu module thiếu/lỗi thì quay về bản cũ vAnalysis. */
async function vAnalysisRoute(){try{if(window.vAnalysisPro)await window.vAnalysisPro();else vAnalysis()}catch(e){console.error("Phân tích v28 lỗi, dùng bản dự phòng:",e);vAnalysis()}}
const ROUTES={"dashboard":vDashboard,"tong-quan":vChartsRoute,"thi-truong":vMarket,"phan-tich":vAnalysisRoute,"danh-muc":vPortfolio,"giao-dich":()=>window.vTradingPage&&window.vTradingPage(),"theo-doi":()=>window.vTheoDoi(),"tin-tuc":vNews,"ai":vAI,"lich-su":()=>window.vLichSu(),"cai-dat":vSettings,"canh-bao":()=>window.vAlerts()};
function route(){tok++;SWR.act.clear();if(typeof dropPro==="function")dropPro();if(chart){chart.remove();chart=null}if(analysisChart){try{window.klinecharts.dispose(analysisChart)}catch{try{analysisChart.dispose()}catch{}}analysisChart=null}const r=(location.hash.replace(/^#\/?/,"")||PREF.start||"dashboard").split("?")[0];$$(".nav").forEach(a=>a.classList.toggle("active",a.dataset.r===r));(ROUTES[r]||vOverview)();window.scrollTo(0,0)}

/* ---------- Cảnh báo (chạy khi NHIP đang mở) ---------- */
let ALS;try{ALS=JSON.parse(localStorage.getItem("nhip.alerts.v1")||"{}")}catch{ALS={}}ALS.rules=ALS.rules||[];ALS.log=ALS.log||[];
const alSave=()=>{ALS.log=ALS.log.slice(0,40);try{localStorage.setItem("nhip.alerts.v1",JSON.stringify(ALS))}catch{}};
const ALT={above:"Giá ≥",below:"Giá ≤",pct:"Biến động ± ≥ (%)",news:"Có tin mới nhắc mã"};
function alFire(r,msg){ALS.log.unshift({t:Date.now(),sym:r.sym,msg});toast("Cảnh báo: "+msg);try{if(PREF.notify&&window.Notification&&Notification.permission==="granted")new Notification("Nhịp Đầu Tư · "+r.sym,{body:msg})}catch{}}
let alBusy=false;
async function alCheck(){if(alBusy)return;const rules=ALS.rules.filter(r=>r.on&&exIn(r.sym));if(!rules.length)return;alBusy=true;try{
 const ps=[...new Set(rules.filter(r=>r.type!=="news").map(r=>r.sym))];let qs=[];if(ps.length){try{qs=await quotes(ps)}catch{}}
 let news=null;if(rules.some(r=>r.type==="news")){try{news=(await api("/api/news")).items}catch{}}
 const today=new Date().toISOString().slice(0,10);
 rules.forEach(r=>{
  if(r.type==="news"){if(!news)return;const re2=new RegExp(`(^|[^A-Za-z0-9])${r.sym}([^A-Za-z0-9]|$)`),hit=news.filter(i=>re2.test(i.title+" "+(i.description||""))).map(i=>i.link);if(!r.seen){r.seen=hit.slice(0,60);return}const nw=news.find(i=>hit.includes(i.link)&&!r.seen.includes(i.link));if(nw){r.seen=[nw.link,...r.seen].slice(0,60);alFire(r,`Tin mới nhắc ${r.sym}: ${nw.title.slice(0,90)}`)}return}
  const q=qs.find(x=>x.symbol===r.sym&&!x.error);if(!q||q.price==null)return;const pv=isIdx(r.sym)?q.price:vnd(q.price);
  if(r.type==="above"&&pv>=r.val){r.on=false;alFire(r,`${r.sym} đạt ${num(pv,0)} (ngưỡng ≥ ${num(r.val,0)})`)}
  else if(r.type==="below"&&pv<=r.val){r.on=false;alFire(r,`${r.sym} còn ${num(pv,0)} (ngưỡng ≤ ${num(r.val,0)})`)}
  else if(r.type==="pct"&&Math.abs(q.changePct)>=r.val&&r.day!==today){r.day=today;alFire(r,`${r.sym} biến động ${pc(q.changePct)} (ngưỡng ±${r.val}%)`)}});
 alSave()}finally{alBusy=false}}
setTimeout(alCheck,8000);setInterval(alCheck,60000);api("/api/portfolios").then(pfSet).catch(()=>{});setTimeout(pfAlerts,15000);setInterval(pfAlerts,120000);
$("#refreshAll").onclick=()=>{SWR.stale();/* v2.87: làm mới mềm — view có dữ liệu tự cập nhật thì chỉ tải lại số liệu tại chỗ, không dựng lại trang (giữ chữ đang nhập và khung AI) */
 const live=SWR.subs.some(s=>{try{return s.ok()}catch{return false}}),h=location.hash;
 if(live&&SWR.act.size){SWR.act.forEach(u=>SWR.get(u).catch(()=>{}));toast("Đang làm mới dữ liệu…")}
 else if(/#\/(giao-dich|ai)(\?|$)/.test(h)){try{window.NHIPTrading&&NHIPTrading.reload&&NHIPTrading.reload()}catch{}toast("Đã làm mới giá")}
 else route()};addEventListener("hashchange",route);
